// Generates /projects/ARCHITECTURE.md from the registry + scanned facts. Never hand-edited.
import { dirname } from 'node:path';

export function writeArchitecture(projects, registry, config) {
  const byId = new Map(projects.map((p) => [p.id, p]));
  const vault = dirname(String(config.vaultProjectsDir ?? '').replaceAll('\\', '/'));
  const out = [
    '<!-- generated by Overmap scan.mjs; do not edit -->',
    '# Architecture map',
    '',
    'Rules for every agent (Claude, Codex) working on these projects:',
    '',
    '- One home per project. Work in the home listed below; new work for a project goes there, not in a new folder.',
    '- Shared services (databases, hosting, mail, payments) are listed under `uses`; reuse them instead of creating new ones.',
    `- The vault (project notes, decisions, memory) lives at ${vault}. Project cards: PROJECT.md in the home, else the vault note.`,
    "- Always update the project's plan before you stop: `PLAN.md` in the home (format at the end of this file), else the checkboxes under docs/superpowers/plans/.",
    '- Never write secrets (tokens, keys, passwords, .env contents) into notes, plans or this file.',
    '- If you land on an old path below, the project has moved: use its home.',
    '',
    '# Projects',
    '',
  ];
  const fam = (e) => String(byId.get(e.id)?.group ?? e.family);
  const nm = (e) => String(byId.get(e.id)?.name ?? e.name);
  const entries = [...registry.values()].sort((a, b) => fam(a).localeCompare(fam(b)) || nm(a).localeCompare(nm(b)));
  for (const e of entries) {
    const p = byId.get(e.id);
    out.push(`## ${nm(e)}`, '');
    out.push(`- id: \`${e.id}\``, `- family: ${fam(e)}`, `- kind: ${e.kind}`, `- status: ${p?.status ?? 'unknown'}`, `- home: \`${e.home}\``);
    const wts = new Map();
    for (const r of p?.repos ?? []) for (const w of r.git?.value?.worktrees ?? []) wts.set(w.path, w.branch);
    const branchOf = (path) => {
      const v = p?.repos?.find((r) => r.path === path)?.git?.value;
      return v ? (v.branch ?? 'detached') : 'unknown';
    };
    if (e.repos.length) out.push(`- repos: ${e.repos.map((r) => `\`${r}\` (${branchOf(r)})`).join(', ')}`);
    if (wts.size) out.push(`- worktrees: ${[...wts].map(([path, br]) => `\`${path}\` (${br ?? 'detached'})`).join(', ')}`);
    const uses = p?.uses ?? e.uses;
    if (uses.length) out.push(`- uses: ${uses.join(', ')}`);
    if (e.oldPaths.length) out.push(`- old paths: ${e.oldPaths.map((o) => `\`${o}\``).join(', ')}`);
    out.push(`- card: ${p?.card ? `\`${p.card}\`` : 'none'}`);
    const pct = p?.plan?.value?.percent;
    out.push(`- plan: ${typeof pct === 'number' ? `${pct}%` : 'none'}`, '');
  }
  out.push(
    '# Plan format', '',
    '- `## ` is a milestone, `### ` is a sprint; items are checkbox lines at any indent.',
    '- Item states: `- [ ]` planned, `- [~]` in progress, `- [!]` blocked, `- [x]` done.',
    '- Put `(due YYYY-MM-DD)` in a milestone or sprint heading to give it a due date.',
    '- End an item with tags `#bug` `#idea` `#test` and an `@owner` if needed.',
    '- A milestone or sprint titled Ideas, Backlog or Improvements makes its untagged items ideas.',
    '- Fenced code blocks and frontmatter are skipped.',
    '',
    '    ## Launch (due 2026-12-01)',
    '    ### Sprint 1',
    '    - [x] Set up hosting @owner',
    '    - [~] Write the signup flow',
    '    - [!] Payment provider approval #bug',
    '    - [ ] Announce the launch',
    '',
    '(The four leading spaces are only so this file does not treat the example as headings; remove them in PLAN.md.)',
    '',
  );
  return out.join('\n');
}
